/**
 * McBot's connector catalog, generated from Hermes' own vetted MCP catalog
 * (hermes/optional-mcps/<name>/manifest.yaml: "presence in this directory = approval"), so every
 * server address and sign-in McBot writes is one Hermes ships (hard rule 2). Remote (http) entries
 * only: McBot's tool block is a URL plus Hermes' OAuth (`auth: oauth`, hermes_cli/mcp_catalog.py
 * _build_server_config). `npm test` fails when the generated file is stale: run
 * `npm run engine:connectors` after a Hermes sync.
 *
 *   npx tsx scripts/hermes-connectors.ts     write src/contracts/connectors.generated.ts
 *   renderConnectors()                        the file's text (used by the test)
 */
import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { parse } from "yaml";

const ROOT = join(import.meta.dirname ?? __dirname, "..");
const DIR = join(ROOT, "hermes/optional-mcps");
export const OUT = join(ROOT, "src/contracts/connectors.generated.ts");

interface Manifest {
  name?: string;
  description?: string;
  source?: string;
  transport?: { type?: string; url?: string };
  auth?: { type?: string; oauth?: Record<string, string | number> };
}

/** "Bases, tables, and records from your Airtable workspace." → first sentence, one line. */
const oneLine = (s: string) => s.replace(/\s+/g, " ").trim().split(/(?<=\.)\s/)[0]!.replace(/\.$/, "");

export function renderConnectors(): string {
  const rows: string[] = [];
  for (const id of readdirSync(DIR).sort()) {
    const file = join(DIR, id, "manifest.yaml");
    if (!existsSync(file)) continue;
    const m = parse(readFileSync(file, "utf8")) as Manifest;
    if (m.transport?.type !== "http" || !m.transport.url || !m.name) continue;
    const auth = m.auth?.type === "oauth" ? "oauth" : m.auth?.type === "none" || !m.auth?.type ? "none" : null;
    if (!auth) continue; // api_key entries need a key flow McBot doesn't model for connectors yet
    // A pinned OAuth client read from the environment (`${ASANA_CLIENT_ID}`): McBot has no place for it yet.
    if (JSON.stringify(m.auth?.oauth ?? {}).includes("${")) continue;
    const oauth = auth === "oauth" && m.auth?.oauth && Object.keys(m.auth.oauth).length ? `, oauth: ${JSON.stringify(m.auth.oauth)}` : "";
    rows.push(`  { name: ${JSON.stringify(m.name)}, does: ${JSON.stringify(oneLine(m.description ?? m.name))}, url: ${JSON.stringify(m.transport.url)}, auth: ${JSON.stringify(auth)}${oauth} },`);
  }
  return [
    "// Generated by scripts/hermes-connectors.ts from hermes/optional-mcps/*/manifest.yaml. Do not edit.",
    "// Run `npm run engine:connectors` after a Hermes sync; `npm test` fails while this file is stale.",
    "",
    "export interface Connector {",
    "  /** The `mcp_servers:` key Hermes' catalog uses. */",
    "  name: string;",
    "  does: string;",
    "  url: string;",
    "  /** \"oauth\": signs in through Hermes (`hermes mcp login <name>`); \"none\": works right away. */",
    "  auth: \"oauth\" | \"none\";",
    "  /** A pre-registered OAuth client the connector pins (`mcp_servers.<name>.oauth`). */",
    "  oauth?: Record<string, string | number>;",
    "}",
    "",
    "export const CONNECTORS: readonly Connector[] = [",
    ...rows,
    "];",
    "",
  ].join("\n");
}

if (process.argv[1] && /hermes-connectors\.ts$/.test(process.argv[1])) {
  writeFileSync(OUT, renderConnectors());
  console.log(`wrote ${OUT}`);
}
